m.tenant_id = #{tenantId}

  AND m.year_month = #{query.yearMonth}


  AND m.workplace_id = #{query.workplaceId}


  AND m.department_id = #{query.departmentId}


  AND (
    e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%')
    OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%')
  )


  AND m.close_status = #{query.closeStatus}


  AND m.block_reason_count > 0

mapper.select:
SELECT d.id AS dailyId, d.employee_id AS employeeId, e.employee_no AS employeeCode, e.employee_name AS employeeName, e.workplace_id AS workplaceId, w.workplace_name AS workplaceName, e.department_id AS departmentId, dept.department_name AS departmentName, d.work_date AS workDate, d.shift_schedule_id AS shiftScheduleId, d.work_day_type AS workDayType, d.status AS status, d.final_status AS finalStatus, d.handling_status AS handlingStatus, d.approval_status AS approvalStatus, d.exception_flag AS exceptionFlag, d.locked_flag AS lockedFlag, d.updated_at AS updatedAt FROM attendance_daily d INNER JOIN employee e ON e.id = d.employee_id AND e.tenant_id = d.tenant_id LEFT JOIN workplace w ON w.id = e.workplace_id AND w.tenant_id = e.tenant_id LEFT JOIN department dept ON dept.id = e.department_id AND dept.tenant_id = e.tenant_id WHERE d.tenant_id = #{tenantId} AND FORMATDATETIME(d.work_date, 'yyyy-MM') = #{query.yearMonth}
AND e.workplace_id = #{query.workplaceId}
AND e.department_id = #{query.departmentId}
AND ( e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%') OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%') )
AND d.employee_id = #{query.employeeId}
ORDER BY d.employee_id, d.work_date, d.id

SELECT item_code, item_name, item_value, item_order, source_json
FROM attendance_monthly_item
WHERE tenant_id = #{tenantId}
  AND monthly_id = #{monthlyId}
  AND deleted_flag = 0
ORDER BY item_order ASC, id ASC

SELECT action_type, operator_id, action_comment, snapshot_json, created_at
FROM attendance_monthly_action_log
WHERE tenant_id = #{tenantId}
  AND monthly_id = #{monthlyId}
  AND deleted_flag = 0
ORDER BY id DESC

SELECT id, close_status AS closeStatus, closed_at AS closedAt, closed_by AS closedBy, reopened_at AS reopenedAt, reopened_by AS reopenedBy, remark
FROM attendance_monthly
WHERE tenant_id = #{tenantId}
  AND year_month = #{yearMonth}
  AND employee_id = #{employeeId}
  AND deleted_flag = 0

mapper.delete:
