  tenant_id, monthly_id, item_code, item_name, item_value, item_order, source_json, created_at, updated_at, deleted_flag
) VALUES (
  #{tenantId}, #{monthlyId}, #{itemCode}, #{itemName}, #{itemValue}, #{itemOrder}, #{sourceJson},
  CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0
)

INSERT INTO attendance_monthly_action_log (
  tenant_id, monthly_id, action_type, operator_id, action_comment, snapshot_json, created_at, deleted_flag
) VALUES (
  #{tenantId}, #{monthlyId}, #{actionType}, #{operatorId}, #{actionComment}, #{snapshotJson}, CURRENT_TIMESTAMP, 0
)

mapper.select:
SELECT id, close_status AS closeStatus, block_reason_count AS blockReasonCount
FROM attendance_monthly
WHERE tenant_id = #{tenantId}
  AND year_month = #{yearMonth}
  AND deleted_flag = 0

    AND workplace_id = #{scopeId}


    AND department_id = #{scopeId}


    AND employee_id = #{scopeId}

ORDER BY employee_id ASC
